CREATE TYPE "GuestPassStatus" AS ENUM ('ACTIVE','CHECKED_IN','REVOKED');
CREATE TABLE "EventStaff" ("id" TEXT NOT NULL,"eventId" TEXT NOT NULL,"userId" TEXT NOT NULL,"role" VARCHAR(20) NOT NULL DEFAULT 'SCANNER',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "EventStaff_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "EventStaff_eventId_userId_key" ON "EventStaff"("eventId","userId");
CREATE TABLE "GuestPass" ("id" TEXT NOT NULL,"eventId" TEXT NOT NULL,"purchaseId" TEXT NOT NULL,"tokenHash" VARCHAR(64) NOT NULL,"guestName" VARCHAR(160),"guestEmail" VARCHAR(254),"guestPhone" VARCHAR(30),"status" "GuestPassStatus" NOT NULL DEFAULT 'ACTIVE',"issuedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"checkedInAt" TIMESTAMP(3),"revokedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "GuestPass_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "GuestPass_tokenHash_key" ON "GuestPass"("tokenHash"); CREATE INDEX "GuestPass_eventId_status_idx" ON "GuestPass"("eventId","status"); CREATE INDEX "GuestPass_purchaseId_idx" ON "GuestPass"("purchaseId");
CREATE TABLE "CheckIn" ("id" TEXT NOT NULL,"passId" TEXT NOT NULL,"eventId" TEXT NOT NULL,"scannerUserId" TEXT NOT NULL,"result" VARCHAR(30) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "CheckIn_pkey" PRIMARY KEY ("id")); CREATE INDEX "CheckIn_eventId_createdAt_idx" ON "CheckIn"("eventId","createdAt");
ALTER TABLE "EventStaff" ADD CONSTRAINT "EventStaff_eventId_fkey" FOREIGN KEY ("eventId") REFERENCES "Event"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "EventStaff" ADD CONSTRAINT "EventStaff_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "GuestPass" ADD CONSTRAINT "GuestPass_eventId_fkey" FOREIGN KEY ("eventId") REFERENCES "Event"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "GuestPass" ADD CONSTRAINT "GuestPass_purchaseId_fkey" FOREIGN KEY ("purchaseId") REFERENCES "GuestPassPurchase"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "CheckIn" ADD CONSTRAINT "CheckIn_passId_fkey" FOREIGN KEY ("passId") REFERENCES "GuestPass"("id") ON DELETE CASCADE ON UPDATE CASCADE;
